CREATE TABLE workflow_reworks(task_id TEXT PRIMARY KEY REFERENCES tasks(id),review_run_id TEXT NOT NULL UNIQUE REFERENCES stage_artifacts(run_id),record_json TEXT NOT NULL,record_hash TEXT NOT NULL);
CREATE TRIGGER immutable_workflow_reworks BEFORE UPDATE ON workflow_reworks BEGIN SELECT RAISE(ABORT,'immutable rework receipt'); END;
CREATE TRIGGER preserve_workflow_reworks BEFORE DELETE ON workflow_reworks BEGIN SELECT RAISE(ABORT,'preserve rework receipt'); END;
CREATE TRIGGER validate_workflow_reworks BEFORE INSERT ON workflow_reworks WHEN NOT EXISTS(SELECT 1 FROM tasks t JOIN stage_runs r ON r.task_id=t.id JOIN stage_artifacts a ON a.run_id=r.id JOIN reservations v ON v.run_id=r.id JOIN task_workflows w ON w.task_id=t.id JOIN workflow_approvals p ON p.task_id=t.id AND p.plan_revision=t.plan_revision JOIN task_budgets b ON b.task_id=t.id WHERE t.id=NEW.task_id AND r.id=NEW.review_run_id AND t.state='needs_review' AND r.role='review' AND r.attempt=1 AND r.state='succeeded' AND r.lease_owner='' AND r.generation=t.generation AND r.plan_revision=t.plan_revision AND v.state='released' AND v.stop_proof_hash=json_extract(a.record_json,'$.reference.stop_proof_hash') AND json_extract(a.record_json,'$.review.valid')=1 AND json_extract(a.record_json,'$.review.document.verdict')='changes_required' AND b.max_reworks=1 AND b.used_reworks=0 AND json_extract(NEW.record_json,'$.task_id')=t.id AND json_extract(NEW.record_json,'$.review_run_id')=r.id AND json_extract(NEW.record_json,'$.generation')=r.generation AND json_extract(NEW.record_json,'$.plan_revision')=r.plan_revision) BEGIN SELECT RAISE(ABORT,'rework requires current released review and approved workflow'); END;
PRAGMA user_version=12;
